-- Review quiz: two distinct questions after previous practice, prioritizing Help.
-- Caption material is private, read only by the existing owner-checked RPC.
create table training_private.training_review_captions (
  skill_code text not null,
  level_number integer not null check (level_number between 1 and 5),
  cue_index integer not null check (cue_index>=0),
  step_title text not null,
  caption text not null,
  cue_at numeric not null check (cue_at>=0),
  primary key(skill_code,level_number,cue_index)
);
alter table training_private.training_review_captions enable row level security;
revoke all on training_private.training_review_captions from public,anon,authenticated;

